 "content": "def transform(grid):
    """Draw color-2 rays from each original clue toward aligned clues."""
    h, w = len(grid), len(grid[0])
    background = grid[0][0]
    out = [row[:] for row in grid]
    clues = [(r, c) for r in range(h) for c in range(w)
             if grid[r][c] != background]

    # Each source mark extends along its row/column toward the nearest other
    # original mark in each direction. The source positions remain unchanged.
    for r, c in clues:
        left = [x for rr, x in clues if rr == r and x < c]
        right = [x for rr, x in clues if rr == r and x > c]
        above = [y for y, cc in clues if cc == c and y < r]
        below = [y for y, cc in clues if cc == c and y > r]
        if left:
            for x in range(max(left) + 1, c):
                if grid[r][x] == background:
                    out[r][x] = 2
        if right:
            for x in range(c + 1, min(right)):
                if grid[r][x] == background:
                    out[r][x] = 2
        if above:
            for y in range(max(above) + 1, r):
                if grid[y][c] == background:
                    out[y][c] = 2
        if below:
            for y in range(r + 1, min(below)):
                if grid[y][c] == background:
                    out[y][c] = 2
    return out
