    h, w = len(grid), len(grid[0])
    background = grid[0][0]
    out = [row[:] for row in grid]

    def repair(indices, get, put):
        # Split foreground indices into runs with a small intervening gap.
        i = 0
        while i < len(indices):
            j = i + 1
            while j < len(indices) and indices[j] - indices[j - 1] <= 3:
                j += 1
            run = indices[i:j]
            # A run of at least three clues indicates a straight line; bridge
            # all bounded gaps up to two cells in that run.
            if len(run) >= 3:
                for a, b in zip(run, run[1:]):
                    if 1 < b - a <= 3:
                        for k in range(a + 1, b):
                            if get(k) == background:
