            i = j

    # Horizontal and vertical strokes, inferred from original foreground only.
    for r in range(h):
        indices = [c for c in range(w) if grid[r][c] != background]
        repair(indices, lambda c, r=r: grid[r][c], lambda c, v, r=r: out[r].__setitem__(c, v))
    for c in range(w):
        indices = [r for r in range(h) if grid[r][c] != background]
        repair(indices, lambda r, c=c: grid[r][c], lambda r, v, c=c: out[r].__setitem__(c, v))
    return out
